import { demoProfile, goals } from "../data/demo-profile.js";
import { scoreAssessment } from "../services/priority-service.js";
import { explainMetric, quickWins } from "../services/explanation-service.js";
import { escapeHtml, label, formatDate, badge, pageHeader, notice } from "../components/ui.js";
import { radioGroup } from "../components/forms.js";

const currentAssessment = state => state.assessments.at(-1);
const resultFor = state => scoreAssessment(currentAssessment(state), state.profile);
const safetyNote = () => `<div class="safety-strip" role="note"><span class="safety-icon" aria-hidden="true">i</span><p><strong>For learning only.</strong> FITSTART helps explain fictional assessment results and does not provide a diagnosis or replace a qualified fitness professional.</p></div>`;

const journeySteps = (active = 1) => `<ol class="journey-steps" aria-label="Your FITSTART journey">
  <li class="${active >= 1 ? "is-done" : ""}"><span>1</span><div><strong>About you</strong><small>Your goal and experience</small></div></li>
  <li class="${active >= 2 ? "is-done" : ""}"><span>2</span><div><strong>Assessment</strong><small>Add and check your results</small></div></li>
  <li class="${active >= 3 ? "is-done" : ""}"><span>3</span><div><strong>Starting point</strong><small>Understand what comes first</small></div></li>
</ol>`;

export function welcomeView() {
  return `<div class="welcome-shell ux-welcome"><nav class="welcome-nav"><a class="brand" href="#/welcome"><span class="brand-mark">FS</span><span>FITSTART</span></a><button class="help-link" data-action="open-boundaries"><span aria-hidden="true">?</span> What is FITSTART?</button></nav><main class="welcome-main" id="main-content"><section class="welcome-copy"><span class="welcome-pill">Made for new gym members</span><h1>Your body assessment, explained one step at a time.</h1><p class="lead">You do not need to understand every number today. FITSTART helps you begin with one result and clearly explains why it matters to your goal.</p><div class="welcome-actions"><a class="button button-primary button-large" href="#/profile/setup">Start my setup <span aria-hidden="true">→</span></a><button class="button button-quiet" data-action="explore-demo">Preview with Maria’s demo</button></div><p class="privacy-reassurance"><span aria-hidden="true">⌂</span> Fictional information stays in this browser and can be cleared anytime.</p></section><aside class="welcome-visual" aria-label="A preview of a simple FITSTART result"><div class="focus-preview friendly-preview"><div class="preview-topline"><span class="badge badge-primary">Start here</span><span class="supporting">1 of 3 priorities</span></div><p class="eyebrow spacer-top">Maria’s main focus</p><h2>Body-Fat Percentage</h2><div class="metric-value"><strong>29</strong><span>%</span></div><div class="plain-explanation"><span aria-hidden="true">💡</span><p><strong>In simple terms</strong><br>This is an estimate of how much of body weight is fat mass.</p></div><a class="preview-link" href="#/welcome" aria-disabled="true">FITSTART will explain why this came first</a></div></aside></main><section class="welcome-how"><p class="eyebrow">How it works</p>${journeySteps(0)}</section></div>`;
}

export function profileSetupView(state) {
  const profile = state.profile || demoProfile;
  return `<div class="content ux-content"><div class="setup-header"><div><a class="back-link" href="#/welcome">← Back</a><p class="eyebrow spacer-top">Step 1 of 3</p><h1>Let’s make this easier for you</h1><p>Three quick answers help FITSTART explain your assessment in the right way. You can add more preferences later.</p></div>${journeySteps(1)}</div><div class="form-focus-layout"><form class="card profile-form ux-form" id="profile-setup-form" novalidate><section class="form-section"><div class="question-number">1</div><div class="field"><label for="displayName">What should we call you?</label><p class="field-help">A first name or nickname is enough.</p><input class="input input-large" id="displayName" name="displayName" value="${escapeHtml(state.profile?.displayName || "")}" autocomplete="nickname" placeholder="For example, Maria" required><p class="field-error" data-error="displayName" aria-live="polite"></p></div></section><section class="form-section"><div class="question-number">2</div><fieldset class="field"><legend>What would you most like to work toward?</legend><p class="field-help">There is no perfect answer. Pick what feels most important right now.</p>${radioGroup("primaryGoal", goals, state.profile?.primaryGoal || "")}<p class="field-error" data-error="primaryGoal" aria-live="polite"></p></fieldset></section><section class="form-section"><div class="question-number">3</div><fieldset class="field"><legend>How familiar are you with fitness assessments?</legend><p class="field-help">This only changes how much detail we explain—not which result comes first.</p>${radioGroup("experience", ["new", "some-experience", "experienced"], state.profile?.experience || "")}<p class="field-error" data-error="experience" aria-live="polite"></p></fieldset></section><input type="hidden" name="secondaryGoal" value="${escapeHtml(state.profile?.secondaryGoal || "")}"><div class="form-actions"><a class="button button-secondary" href="#/welcome">Not now</a><button class="button button-primary" type="submit">Save and continue <span aria-hidden="true">→</span></button></div></form><aside class="reassurance-panel"><div class="reassurance-icon" aria-hidden="true">✓</div><h2>You’re in control</h2><ul class="friendly-list"><li>No medical-history questions</li><li>No real health data is needed for this prototype</li><li>Your answers can be changed later</li><li>Nothing is shared with a trainer</li></ul></aside></div></div>`;
}

export function dashboardView(state) {
  const assessment = currentAssessment(state);
  const result = resultFor(state);
  const name = escapeHtml(state.profile?.displayName || "Member");
  if (!assessment) {
    return `<div class="content ux-content"><header class="friendly-header"><div><p class="eyebrow">Your home</p><h1>You’re ready for the next step, ${name}.</h1><p>Your profile is saved. Now add a fictional FitMao assessment so FITSTART can explain it.</p></div><span class="progress-badge">1 of 3 steps complete</span></header>${journeySteps(1)}<section class="next-action-card"><div class="next-action-icon" aria-hidden="true">2</div><div><p class="eyebrow">Your next step</p><h2>Add an assessment</h2><p>For your first visit, we recommend using Maria’s demo. You will review every value before anything is calculated.</p></div><a class="button button-primary button-large" href="#/assessment/import">Choose an assessment method →</a></section><div class="two-columns results-section"><div class="card quiet-card"><p class="eyebrow">Want to learn first?</p><h3>Browse common assessment terms</h3><p>Plain-language definitions are available without adding an assessment.</p><a class="text-link" href="#/learn">Open the Metric Library →</a></div><div class="card profile-mini"><span class="avatar" aria-hidden="true">${name.slice(0, 1).toUpperCase()}</span><div><p class="eyebrow">Your saved goal</p><h3>${label(state.profile?.primaryGoal)}</h3><a class="text-link" href="#/profile">Review profile</a></div></div></div>${safetyNote()}</div>`;
  }

  const main = result.mainFocus;
  const explanation = main ? explainMetric(main, state.profile) : null;
  return `<div class="content ux-content"><header class="friendly-header"><div><p class="eyebrow">Your home</p><h1>Good to see you, ${name}.</h1><p>Your latest starting point is ready. You only need to begin with one result.</p></div><a class="button button-secondary" href="#/profile">Your profile</a></header><section class="dashboard-focus"><div class="focus-kicker"><span class="badge badge-primary">Start here</span><span>Latest assessment · ${formatDate(assessment.assessedAt)}</span></div><div class="dashboard-focus-grid"><div><p class="eyebrow">Your Main Focus</p><h2>${escapeHtml(main?.name || "Review your assessment")}</h2><p class="focus-summary">${escapeHtml(explanation?.meaning || "More information is needed before a priority can be created.")}</p><div class="why-inline"><span aria-hidden="true">💡</span><p>${escapeHtml(explanation?.why || "Review the confirmed values to continue.")}</p></div><a class="button button-primary button-large" href="#/results">Explain my starting point →</a></div>${main ? `<div class="value-panel"><p>Original report value</p><strong>${main.value}</strong><span>${escapeHtml(main.unit)}</span>${badge(main)}<small>FITSTART never changes this value.</small></div>` : ""}</div></section><section class="dashboard-actions"><article class="mini-action"><span class="mini-action-icon" aria-hidden="true">＋</span><div><h3>Add another assessment</h3><p>Review a new fictional report.</p></div><a href="#/assessment/import" aria-label="Add another assessment">→</a></article><article class="mini-action ${state.assessments.length < 2 ? "is-muted" : ""}"><span class="mini-action-icon" aria-hidden="true">↔</span><div><h3>Compare two reports</h3><p>${state.assessments.length < 2 ? "Available after your next assessment." : "See measured differences only."}</p></div>${state.assessments.length < 2 ? `<span aria-hidden="true">—</span>` : `<a href="#/compare" aria-label="Compare two reports">→</a>`}</article><article class="mini-action"><span class="mini-action-icon" aria-hidden="true">?</span><div><h3>Learn a term</h3><p>Use plain-language definitions.</p></div><a href="#/learn" aria-label="Open the Metric Library">→</a></article></section>${safetyNote()}</div>`;
}

export function assessmentImportView() {
  return `<div class="content ux-content"><div class="setup-header compact"><div><a class="back-link" href="#/dashboard">← Back to Home</a><p class="eyebrow spacer-top">Add an assessment</p><h1>How would you like to begin?</h1><p>For this prototype, every method uses fictional values and includes a review step.</p></div>${journeySteps(2)}</div><div class="recommended-method"><div><span class="recommend-label">Recommended for your first visit</span><div class="method-heading"><span class="method-icon" aria-hidden="true">▶</span><div><h2>Try Maria’s demo assessment</h2><p>See the complete experience without uploading anything. It takes about two minutes.</p></div></div></div><button class="button button-primary button-large" data-action="use-demo-assessment">Use demo assessment →</button></div><p class="or-divider"><span>or preview another method</span></p><section class="method-grid"><article class="card method-card simple-method"><div class="method-icon" aria-hidden="true">▣</div><h2>Upload a screenshot</h2><p>Choose a report image, then review the simulated captured values.</p><div class="field spacer-top"><label for="report-upload">Choose a report image</label><input class="input" id="report-upload" type="file" accept="image/*"><p class="field-help">The image is temporary and is not saved in browser storage.</p></div><button class="button button-secondary" data-action="simulate-screenshot">Preview screenshot flow</button></article><article class="card method-card simple-method"><div class="method-icon" aria-hidden="true">⌗</div><h2>Use a QR result</h2><p>Preview how a FitMao QR handoff could work in a future version.</p><div class="qr-placeholder" aria-hidden="true"><span>⌗</span><small>Simulated QR</small></div><button class="button button-secondary" data-action="simulate-qr">Preview QR flow</button></article></section>${notice("Screenshot reading and QR scanning are visual simulations. You will always review the values before FITSTART creates a starting point.", "warning", "Nothing is calculated yet")}</div>`;
}

export function assessmentReviewView(state) {
  const assessment = state.draftAssessment;
  if (!assessment) return `<div class="content"><div class="card empty-state"><div class="empty-icon" aria-hidden="true">i</div><h1>No assessment to review</h1><p>Choose an assessment method first.</p><a class="button button-primary spacer-top" href="#/assessment/import">Choose a method</a></div></div>`;
  const previous = currentAssessment(state);
  const raw = assessment.metrics.map(metric => `<div class="raw-row"><span>${escapeHtml(metric.name)}</span><strong>${metric.value === "" || metric.value === null ? "—" : escapeHtml(metric.value)} ${escapeHtml(metric.unit)}</strong></div>`).join("");
  return `<div class="content ux-content"><div class="setup-header compact"><div><a class="back-link" href="#/assessment/import">← Change method</a><p class="eyebrow spacer-top">Review before continuing</p><h1>Do these numbers match the report?</h1><p>Compare each value with the preview. If something looks wrong, correct it now. No priority is created until you confirm.</p></div><div class="review-status"><span aria-hidden="true">7</span><p><strong>measurement fields</strong><br><small>to check</small></p></div></div>${notice(assessment.sourceType === "demo" ? "These are fictional demo values for Maria." : "The captured values below are simulated.", "warning", "Your only job on this screen: check the numbers")}<form id="assessment-review-form" novalidate><div class="review-layout"><section><div class="metric-review-list">${assessment.metrics.map((metric, index) => `<article class="metric-review-card"><div class="metric-review-heading"><span class="metric-number">${index + 1}</span><div><h2>${escapeHtml(metric.name)}</h2><p class="field-error" data-error="${metric.id}" aria-live="polite"></p></div><span class="check-hint">Check</span></div><div class="metric-review-controls"><div class="field value-field"><label for="metric-${metric.id}">Report value</label><div class="unit-input"><input class="input" id="metric-${metric.id}" name="metric-${metric.id}" type="number" step="any" value="${metric.value === null ? "" : escapeHtml(metric.value)}" ${metric.value === null ? "disabled" : ""}><span>${escapeHtml(metric.unit)}</span></div></div><div class="field category-field"><label for="category-${metric.id}">Report label</label><select class="select" id="category-${metric.id}" name="category-${metric.id}"><option value="within" ${metric.sourceCategory === "within" ? "selected" : ""}>Within reference range</option><option value="attention" ${metric.sourceCategory === "attention" ? "selected" : ""}>Needs review</option><option value="higher-attention" ${metric.sourceCategory === "higher-attention" ? "selected" : ""}>Higher attention</option></select></div></div><div class="metric-review-actions"><button class="text-link" type="button" data-action="toggle-unavailable" data-id="${metric.id}">${metric.value === null ? "Restore this measurement" : "This measurement is unavailable"}</button><button class="text-link" type="button" data-action="reset-metric" data-id="${metric.id}">Reset value</button></div></article>`).join("")}</div>${previous ? notice("FITSTART will compare this only with the immediately previous assessment and will ask you to verify unusually large differences.", "warning", "A previous assessment is available") : ""}<label class="confirmation-box"><input type="checkbox" name="reviewed" required><span><strong>Yes, I checked the available values.</strong><small>They match the fictional report preview.</small></span></label><p class="field-error" data-error="reviewed" aria-live="polite"></p><div class="sticky-actions"><a class="button button-secondary" href="#/assessment/import">Go back</a><button class="button button-primary button-large" type="submit">Confirm and continue →</button></div></section><aside class="report-preview-sticky"><details class="report-details" open><summary>Fictional report preview</summary><div class="raw-report"><div class="raw-report-header"><strong>FITMAO-STYLE DEMO REPORT</strong><p>Fictional values · ${escapeHtml(assessment.sourceType)}</p></div>${raw}<p class="supporting spacer-top">Preview only. No professional verification or live FitMao connection.</p></div></details></aside></div></form></div>`;
}

export function resultsView(state) {
  const assessment = currentAssessment(state);
  if (!assessment) return `<div class="content"><div class="card empty-state"><h1>No confirmed result yet</h1><p>Add and confirm an assessment first.</p><a class="button button-primary spacer-top" href="#/assessment/import">Add assessment</a></div></div>`;
  const result = resultFor(state);
  if (result.insufficient) return `<div class="content">${pageHeader("Your starting point", "We need a little more information", "FITSTART could not create an honest priority from the available confirmed values.")}${notice("Missing measurements are excluded, never silently scored as zero.", "warning", "Review the assessment")}<a class="button button-primary" href="#/assessment/review">Check assessment values</a></div>`;
  const main = result.mainFocus;
  const explanation = explainMetric(main, state.profile);
  const wins = quickWins(state.profile);
  const memberName = escapeHtml(state.profile?.displayName || "Member");
  return `<div class="content ux-content"><header class="result-header"><div><a class="back-link" href="#/dashboard">← Back to Home</a><p class="eyebrow spacer-top">${memberName}’s Personalized Starting Point</p><h1>You only need to start with one thing.</h1><p>Assessment from ${formatDate(assessment.assessedAt)} · Original values remain unchanged.</p></div><a class="button button-secondary research-link" href="#/research-comparison">Research view</a></header>${safetyNote()}<div class="result-map" aria-label="How to read this page"><span class="is-current"><b>1</b> Start here</span><span><b>2</b> Understand why</span><span><b>3</b> Explore next steps</span></div><article class="card main-focus ux-main-focus"><div class="main-focus-grid"><div><span class="badge">Your Main Focus</span><p class="eyebrow spacer-top">Begin by understanding this result</p><h2>${escapeHtml(main.name)}</h2><div class="plain-explanation light"><span aria-hidden="true">💡</span><p><strong>What this means</strong><br>${escapeHtml(explanation.meaning)}</p></div><a class="button button-light button-large spacer-top" href="#/results/metric/${main.id}">See the simple explanation →</a></div><div class="value-panel dark"><p>From the original report</p><strong>${main.value}</strong><span>${escapeHtml(main.unit)}</span>${badge(main)}<small>This value has not been changed.</small></div></div></article><section class="results-section"><div class="section-heading numbered-heading"><span>2</span><div><p class="eyebrow">Why this came first</p><h2>Based on your answer and your report</h2><p>No hidden guesswork—these are the two inputs that mattered.</p></div></div><div class="why-grid friendly-why"><div class="why-callout"><span class="callout-icon" aria-hidden="true">◎</span><strong>You told us</strong><p>${escapeHtml(explanation.toldUs)}</p></div><div class="why-callout"><span class="callout-icon" aria-hidden="true">▤</span><strong>Your report showed</strong><p>${escapeHtml(explanation.showed)}</p></div></div></section><section class="results-section"><div class="section-heading numbered-heading"><span>3</span><div><p class="eyebrow">Next, when you are ready</p><h2>Two other results to understand</h2><p>These are not extra tasks. They are simply the next results in the demonstration order.</p></div></div><div class="priority-list friendly-priorities">${result.priorities.map((item, index) => { const itemExplanation = explainMetric(item, state.profile); return `<article class="card priority-card"><span class="priority-rank">${index + 2}</span><div><p class="supporting">Priority ${index + 2}</p><h3>${escapeHtml(item.name)}</h3><p class="priority-value">${item.value} ${escapeHtml(item.unit)} <span>· ${escapeHtml(item.sourceCategoryLabel.replace("Demo: ", ""))}</span></p><p class="supporting">${escapeHtml(itemExplanation.meaning)}</p></div><a class="button button-secondary" href="#/results/metric/${item.id}">Explain this</a></article>`; }).join("")}</div></section><section class="results-section next-step-section"><div class="card card-accent first-step-card"><span class="next-step-label">A good first step</span><h2>Write down one question</h2><p>Open the explanation for ${escapeHtml(main.name)} and note one thing you would like a qualified fitness professional to clarify.</p><a class="button button-secondary spacer-top" href="#/results/metric/${main.id}">Open my Main Focus</a></div><div class="card"><p class="eyebrow">Small, realistic actions</p><h2>Your Quick Wins</h2><div class="stack spacer-top">${wins.map(win => `<div class="quick-win"><p>${escapeHtml(win)}</p></div>`).join("")}</div></div></section><details class="more-section results-section"><summary><span><strong>Explore more about this assessment</strong><small>Connections, definitions, and the complete original report</small></span><span aria-hidden="true">＋</span></summary><div class="more-section-body"><div class="two-columns"><div class="card"><p class="eyebrow">How results connect</p><h2>Consider these together</h2><div class="connection-line spacer-top"><strong>${escapeHtml(main.name)}</strong><span class="connection-link" aria-hidden="true">↔</span><strong>${escapeHtml(result.priorities[0]?.name || "Related results")}</strong></div><p class="supporting spacer-top">These measurements can be considered together. This does not mean one caused the other.</p></div><div class="card card-soft"><p class="eyebrow">Learn at your pace</p><h2>Metric Mini-Library</h2><p>Read plain-language definitions and important limitations.</p><a class="button button-soft spacer-top" href="#/learn">Explore the library</a></div></div><div class="card original-report-card"><div><p class="eyebrow">Complete original assessment</p><h2>See every confirmed value</h2><p>Nothing is replaced or hidden by the personalized presentation.</p></div><button class="button button-secondary" data-action="view-full-assessment">View original values</button></div></div></details><div class="professional-banner"><span aria-hidden="true">i</span><div><strong>Take this result into a conversation—not as a diagnosis.</strong><p>Consider discussing the assessment with a qualified fitness professional before making changes based on a measurement.</p></div></div></div>`;
}
